def evaluate(current_reputation, observation, my_history, round_num):
    reputation = current_reputation

    # Update reputation based on observed actions from others
    if 'action' in observation and observation['action']:
        action = observation['action']
        if action == 'cooperate':
            reputation += 0.4  # Positive reinforcement for cooperation
        elif action == 'defect':
            reputation -= 0.4  # Negative reinforcement for defection

        # Use recent_window if available to weight recent actions more
        recent_window = observation.get('recent_window', [])
        if recent_window:
            recent_coops = sum(1 for w in recent_window if w.get('action') == 'cooperate')
            recent_total = len(recent_window)
            if recent_total > 0:
                recent_ratio = recent_coops / recent_total
                # Adjust reputation based on recent trend
                if recent_ratio > 0.7:
                    reputation += 0.2
                elif recent_ratio < 0.3:
                    reputation -= 0.2

        # Clamp reputation between -1 and 1
        reputation = max(-1.0, min(1.0, reputation))

    return reputation

def decide(recipient_reputation, round_num, my_history):
    # Base decision on recipient's reputation
    if recipient_reputation > 0.2:
        return True  # Cooperate with high-reputation agents
    elif recipient_reputation < -0.2:
        return False  # Defect against low-reputation agents
    else:
        # In the middle range, use exploration based on own history
        coop_count = sum(1 for h in my_history if h.get('action') == 'cooperate')
        total = len(my_history)
        coop_rate = coop_count / total if total > 0 else 0.5

        # If I've been cooperative overall, lean toward cooperation
        # Add some randomness to avoid predictable patterns
        if coop_rate > 0.6:
            return random.random() < 0.7
        elif coop_rate < 0.4:
            return random.random() < 0.3
        else:
            return random.random() < 0.5

    return random.random() >= 0.5

